const input=$json.body??$json;
const status=String(input.milestone_status??input.status??'').toLowerCase();
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const closingDate=String(input.closing_date??'').trim();
const milestones=Array.isArray(input.milestones)?input.milestones:[];
const requiredEvidence=Array.isArray(input.required_evidence)?input.required_evidence:[];
const verifiedEvidence=Array.isArray(input.verified_evidence)?input.verified_evidence:[];
const failedEvidence=Array.isArray(input.failed_evidence)?input.failed_evidence:[];
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const identityReady=Boolean(dealId&&leadId&&propertyId);
const evidenceComplete=requiredEvidence.length===0||requiredEvidence.every(req=>verifiedEvidence.some(v=>String(v.id??v.type??v).toLowerCase()===String(req.id??req.type??req).toLowerCase()));
const failed=failedEvidence.length>0;
const incompleteMilestones=milestones.filter(m=>!['completed','verified'].includes(String(m.status??'').toLowerCase()));
let evidence_status='needs_review',next='WF-126',reason='closing evidence reconciliation requires review';
if(input.dnc===true){evidence_status='blocked_dnc';reason='DNC/contact restriction';}
else if(blockers.length){evidence_status='blocked';reason='active closing blockers';}
else if(!identityReady){evidence_status='incomplete_identity';reason='deal/property/lead identity incomplete';}
else if(!closingDate){evidence_status='closing_date_missing';reason='closing date missing';}
else if(failed){evidence_status='evidence_failed';next='WF-327';reason='one or more required closing evidence items failed';}
else if(!evidenceComplete){evidence_status='evidence_gap';next='WF-327';reason='required closing evidence is not fully verified';}
else if(incompleteMilestones.length){evidence_status='milestones_incomplete';next='WF-325';reason='closing milestones remain incomplete';}
else if(status==='overdue'||status==='critical_due_soon'){evidence_status='recovery_required';next='WF-327';reason='critical timing requires evidence/recovery routing';}
else{evidence_status='reconciled';next='WF-327';reason='required closing evidence and supplied milestones reconcile successfully';}
return [{json:{...input,workflow_id:'WF-326',workflow_name:'Milestone Update → Closing Evidence Reconciliation & Recovery Routing Controller',evidence_status,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,closing_date:closingDate||null,required_evidence_count:requiredEvidence.length,verified_evidence_count:verifiedEvidence.length,failed_evidence_count:failedEvidence.length,incomplete_milestone_count:incompleteMilestones.length,next_workflow:next,human_review_required:!['reconciled','evidence_gap','evidence_failed','recovery_required'].includes(evidence_status),crm_activity:{activity_type:'closing_evidence_reconciliation',deal_id:dealId,lead_id:leadId,property_id:propertyId,status:evidence_status,closing_date:closingDate||null,reason}}}];
